import net.minecraft.world.level.block.state.BlockState;
/** Independently frozen shallow placements plus native deep generation, queries and saved edits. */
public final class UraniumSmoke {
 static boolean uranium(BlockState state){return state.is(UraniumContent.ORE)||state.is(UraniumContent.DEEPSLATE_ORE);}
 static void require(boolean b,String m){RadiationSmoke.require(b,m);}
 public static void verify(ServerLevel l,Path d)throws Exception{materials(l);legacy(l,d);RadiationSmoke.verify(l);UraniumWeaponSmoke.verify(l,d);natural(l,d);}
 private static void materials(ServerLevel l){var manager=l.getServer().getRecipeManager();for(var material:List.of(UraniumContent.RAW,UraniumContent.ORE.asItem(),UraniumContent.DEEPSLATE_ORE.asItem())){var input=new SingleRecipeInput(new ItemStack(material));for(var type:List.of(RecipeType.SMELTING,RecipeType.BLASTING))require(manager.getRecipeFor(type,input,l).orElseThrow().value().assemble(input).is(UraniumContent.INGOT),"native uranium processing");}var in=CraftingInput.of(1,1,List.of(new ItemStack(UraniumContent.INGOT)));var tips=manager.getRecipeFor(RecipeType.CRAFTING,in,l).orElseThrow().value().assemble(in);require(tips.is(UraniumContent.TIP)&&tips.getCount()==4,"restrained tip crafting");var diamond=new ItemStack(Items.DIAMOND_PICKAXE);for(var ore:List.of(UraniumContent.ORE,UraniumContent.DEEPSLATE_ORE)){require(diamond.isCorrectToolForDrops(ore.defaultBlockState())&&!new ItemStack(Items.IRON_PICKAXE).isCorrectToolForDrops(ore.defaultBlockState()),"late diamond harvest");require(Block.getDrops(ore.defaultBlockState(),l,BlockPos.ZERO,null,null,diamond).getFirst().is(UraniumContent.RAW),"native raw uranium drop");}}
 private static void legacy(ServerLevel l,Path d)throws Exception{
  long shallow=0,deep=0;int added=0;java.util.function.Predicate<BlockState> predicate=UraniumSmoke::uranium;
  require(OreLayer.MAX_DEPTH==224&&!new OreLayer(1,0,0,13,0,0).maybeHas(predicate)&&new OreLayer(1,0,0,14,0,0).maybeHas(predicate),"versioned uranium predicates with retained shallow224 bound");
  try(var loader=MetallurgySmoke.historicalReader(Path.of(System.getProperty("blockbranch.oldResoniteClasses")).toUri().toURL())){
   var old=loader.loadClass("blockbranch.realistic.OreLayer");var ctor=old.getConstructor(long.class,int.class,int.class,int.class,int.class,int.class);var bind=old.getMethod("bind",int.class,int.class);var state=old.getMethod("state",int.class,int.class,int.class,int.class,BlockState.class,boolean.class);
   for(long seed:new long[]{424242,1,-17})for(int cx:new int[]{-1,0,1}){
    var frozen=bind.invoke(ctor.newInstance(seed,cx,-1,13,65535,65535),64,64);var retained=new OreLayer(seed,cx,-1,13,65535,65535).bind(64,64);var current=new OreLayer(seed,cx,-1,14,65535,65535).bind(64,64);
    for(boolean caves:new boolean[]{false,true})for(int z=0;z<16;z++)for(int x=0;x<16;x++)for(int depth=4;depth<=224;depth+=2){int y=64-depth;var host=(y<0?Blocks.DEEPSLATE:Blocks.STONE).defaultBlockState();var expected=(BlockState)state.invoke(frozen,x,y,z,64,host,caves);require(retained.state(x,y,z,64,host,caves)==expected&&current.state(x,y,z,64,host,caves)==expected,"published shallow placements exact under13/14");shallow++;}
    for(int z=0;z<16;z++)for(int x=0;x<16;x++)for(int depth=8000;depth<=10000;depth+=8){int y=64-depth;var host=Blocks.DEEPSLATE.defaultBlockState();require(retained.state(x,y,z,64,host)==host&&state.invoke(frozen,x,y,z,64,host,false)==host,"old definitions never backfill deep ore");var next=current.state(x,y,z,64,host);require(next==host||uranium(next),"only uranium in new deep band");if(uranium(next))added++;deep++;}
    require(!current.mayAffect((64-4000)>>4,64,64)&&current.mayAffect((64-9000)>>4,64,64)&&!retained.mayAffect((64-9000)>>4,64,64),"separate deep band skips gap and old definitions");
    var field=old.getDeclaredField("index");field.setAccessible(true);var a=field.get(frozen);var now=OreLayer.class.getDeclaredField("index");now.setAccessible(true);var b=now.get(current);for(var key:List.of("ny","refs","values")){var m=a.getClass().getDeclaredMethod(key);m.setAccessible(true);var n=b.getClass().getDeclaredMethod(key);n.setAccessible(true);var av=m.invoke(a);var bv=n.invoke(b);require(av instanceof Integer?av.equals(bv):java.lang.reflect.Array.getLength(av)==java.lang.reflect.Array.getLength(bv),"deep band does not widen shallow index "+key);}
   }
   try{old.getMethod("decode",net.minecraft.nbt.CompoundTag.class).invoke(null,new OreLayer(1,0,0,14,0,0).encode());throw new AssertionError("old13 accepted14");}catch(java.lang.reflect.InvocationTargetException expected){require(expected.getCause() instanceof IllegalArgumentException,"old descriptor refusal");}
   var guard=loader.loadClass("blockbranch.cubic.ColumnWorldFormat").getMethod("check",Path.class,boolean.class,boolean.class,boolean.class);for(boolean decoration:new boolean[]{false,true}){var root=Files.createTempDirectory(d,"old-resonite-");ColumnWorldFormat.check(root,false,decoration,true);var marker=root.resolve("blockbranch-columns.txt");String before=Files.readString(marker);try{guard.invoke(null,root,true,decoration,true);throw new AssertionError("old18 accepted19");}catch(java.lang.reflect.InvocationTargetException expected){require(expected.getCause() instanceof IllegalStateException,"old catalog refusal");}require(Files.readString(marker).equals(before),"old refusal preserves marker");}
  }
  for(int depth=0;depth<8000;depth++)require(!UraniumVeins.contains(424242,0,-depth,0,depth),"no uranium above8km");require(added>0,"deep positive witnesses");blockbranch.Blockbranch.LOGGER.info("URANIUM frozenShallow13={} deepComparisons={} added={} old14/19 refusal=true shallowIndexUnchanged=true",shallow,deep,added);
 }
 private static void natural(ServerLevel l,Path d)throws Exception{
  if(!(l.getChunkSource().getGenerator() instanceof RealisticGenerator g))return;if(g.oreDefinition()<14){require(g.oreDefinition()>=3&&g.oreDefinition()<=13,"retained ore definition");return;}require(g.oreDefinition()>=14,"current uranium definition");var marker=d.resolve("uranium-mined.txt");if(Files.exists(marker)){var v=Files.readString(marker).trim().split(",");var pos=new BlockPos(Integer.parseInt(v[0]),Integer.parseInt(v[1]),Integer.parseInt(v[2]));var base=((SparseColumn)l.getChunkAt(pos)).blockbranch$terrain().base();require(l.getBlockState(pos).isAir()&&uranium(base.state(pos.getX(),pos.getY(),pos.getZ())),"deep edit survives relaunch without changing procedural base");return;}
  var origin=g.getOrigin(l.getChunkSource().randomState());boolean found=false;search:for(int dz=0;dz<4;dz++)for(int dx=0;dx<4;dx++){var chunk=l.getChunk(origin.x()+dx,origin.z()+dz);var base=((SparseColumn)chunk).blockbranch$terrain().base();var restored=TerrainProfile.decode(base.encode(l.palettedContainerFactory()),l.palettedContainerFactory());require(base.ores().definition()>=14,"native descriptor14");long oreSeed=base.ores().encode().getLong("seed").orElseThrow();for(int z=0;z<16;z++)for(int x=0;x<16;x++)for(int depth=8000;depth<=10000;depth++){int y=base.groundHeight(x,z)-depth,wx=chunk.getPos().getMinBlockX()+x,wz=chunk.getPos().getMinBlockZ()+z;if(!UraniumVeins.contains(oreSeed,wx,y,wz,depth))continue;var value=base.state(x,y,z);if(!uranium(value))continue;var pos=new BlockPos(wx,y,wz);require(l.getBlockState(pos)==value&&restored.state(x,y,z)==value&&depth>=8000,"native deep ore/profile snapshot agrees");int expected=ColumnLimits.MIN_Y;for(int sy=base.groundHeight(x,z)-8000;sy>=base.groundHeight(x,z)-10000;sy--)if(uranium(base.state(x,sy,z))){expected=sy+1;break;}require(base.top(UraniumSmoke::uranium,x,z,base.groundHeight(x,z))==expected&&base.top(UraniumSmoke::uranium,x,z,base.groundHeight(x,z)-4000)==expected,"deep-only height query skips untouched gap");l.setBlock(pos,Blocks.AIR.defaultBlockState(),2);Files.writeString(marker,pos.getX()+","+pos.getY()+","+pos.getZ());l.getServer().saveEverything(false,true,true);blockbranch.Blockbranch.LOGGER.info("URANIUM native natural witness={} depth={}",pos,depth);found=true;break search;}}require(found,"bounded native deep witness");
 }
 private UraniumSmoke(){}
}
